import { chromium, webkit } from 'playwright';
const TARGET=process.env.TARGET_URL||'https://gisoogholizade-ux.github.io/lifelingo/';
const PHASE=process.env.PHASE||'landing', WIDTH=Number(process.env.WIDTH||390), ENGINE=process.env.ENGINE==='webkit'?webkit:chromium;
const log=(k,v='')=>console.log(`[PHASE:${PHASE}] ${k}${v!==''?' '+(typeof v==='string'?v:JSON.stringify(v)):''}`), fail=m=>{throw new Error(`[PHASE:${PHASE}] ${m}`)}, ok=(c,m)=>{if(!c)fail(m);log('PASS',m)};
const browser=await ENGINE.launch({headless:true}), page=await browser.newPage({viewport:{width:WIDTH,height:844},isMobile:true,hasTouch:true});
page.setDefaultTimeout(3500);page.on('pageerror',e=>log('PAGEERROR',e.message));page.on('console',m=>{if(m.type()==='error')log('CONSOLE_ERROR',m.text())});
await page.addInitScript(()=>{
 window.__P={ticks:0,uniqueAdds:0,rawAdds:0,hash:0,pop:0};
 addEventListener('DOMContentLoaded',()=>{const seen=new WeakSet();setInterval(()=>window.__P.ticks++,20);new MutationObserver(rs=>{for(const r of rs)for(const n of r.addedNodes||[]){if(n.nodeType!==1)continue;const missions=[];if(n.id==='speakMission')missions.push(n);missions.push(...(n.querySelectorAll?.('#speakMission')||[]));for(const m of missions){window.__P.rawAdds++;if(!seen.has(m)){seen.add(m);window.__P.uniqueAdds++}}}}).observe(document.body,{subtree:true,childList:true})},{once:true});
 addEventListener('hashchange',()=>window.__P.hash++);addEventListener('popstate',()=>window.__P.pop++);
});
await page.goto(TARGET,{waitUntil:'networkidle',timeout:45000});await page.waitForTimeout(700);
await page.evaluate(()=>{document.querySelector('#authScreen')?.classList.add('hidden');document.querySelector('#appScreen')?.classList.remove('hidden');document.querySelector('#onboarding')?.classList.add('hidden');if(!window.llSupabase)throw new Error('llSupabase missing');window.llSupabase.auth.getSession=async()=>({data:{session:{access_token:'PHASE_TEST'}},error:null})});
const snap=()=>page.evaluate(()=>({hash:location.hash,active:[...document.querySelectorAll('.view.on')].map(x=>x.id),mission:document.querySelectorAll('#speakMission').length,parent:document.querySelector('#speakMission')?.parentElement?.id||'',premium:document.querySelectorAll('.llPremiumStage').length,inert:[...document.querySelectorAll('[inert]')].map(x=>x.id||x.className||x.tagName),bodyPE:getComputedStyle(document.body).pointerEvents,htmlPE:getComputedStyle(document.documentElement).pointerEvents,ticks:window.__P.ticks,uniqueAdds:window.__P.uniqueAdds,rawAdds:window.__P.rawAdds,hashchange:window.__P.hash,popstate:window.__P.pop}));
async function alive(label){const a=await page.evaluate(()=>window.__P.ticks);await page.waitForTimeout(120);const b=await page.evaluate(()=>window.__P.ticks);ok(b-a>=3,`${label} main-thread alive ${a}->${b}`)}
async function nav(n){await page.locator(`[data-nav="${n}"]:visible`).first().click();await page.waitForTimeout(35);const s=await snap();ok(s.active.length===1&&s.active[0]===`view-${n}`,`nav ${n} active=${s.active.join(',')}`);return s}
async function openAirport(){const before=await page.evaluate(()=>window.__P.uniqueAdds);await page.locator('[data-canonical-scenario="airport"]:visible').first().click();await page.waitForTimeout(80);const s=await snap();ok(s.hash==='#speak/scenario/airport',`airport hash ${s.hash}`);ok(s.mission===1,`airport mission count ${s.mission}`);ok(s.parent==='speakRoot',`airport parent ${s.parent}`);ok(s.premium===1,`premium stage count ${s.premium}`);ok(s.inert.length===0,'airport inert empty');ok(s.bodyPE!=='none'&&s.htmlPE!=='none',`airport pointer ${s.bodyPE}/${s.htmlPE}`);ok(s.uniqueAdds-before===1,`airport unique mount delta ${s.uniqueAdds-before}`);await alive('airport');return s}
async function back(){await page.locator('[data-mission-exit]:visible').first().click();await page.waitForTimeout(45);const s=await snap();ok(s.hash==='#speak'&&s.mission===0,`back clean hash=${s.hash} mission=${s.mission}`);ok(s.inert.length===0&&s.bodyPE!=='none','back input restored');await alive('back');return s}
async function hit(sel){const b=await page.locator(sel).first().boundingBox();if(!b)return null;return page.evaluate(({x,y})=>{const sm=e=>{if(!e)return null;const s=getComputedStyle(e);return{tag:e.tagName,id:e.id||'',cls:String(e.className||''),position:s.position,zIndex:s.zIndex,pointerEvents:s.pointerEvents,display:s.display,visibility:s.visibility,opacity:s.opacity}};return{top:sm(document.elementFromPoint(x,y)),stack:document.elementsFromPoint(x,y).slice(0,10).map(sm)}},{x:b.x+b.width/2,y:b.y+b.height/2})}
try{
 log('START',{engine:process.env.ENGINE||'chromium',width:WIDTH});
 if(PHASE==='landing'){await nav('home');const before=await snap();await nav('speak');const after=await snap();ok(after.hash==='#speak','landing hash #speak');ok(after.mission===0,'landing mission absent');ok(after.inert.length===0,'landing inert empty');ok(after.bodyPE!=='none'&&after.htmlPE!=='none','landing pointer enabled');await alive('landing');log('HIT_HOME',await hit('[data-nav="home"]:visible'));log('HIT_LEARN',await hit('[data-nav="learn"]:visible'));log('HIT_PROFILE',await hit('[data-nav="profile"]:visible'));log('STATE',{before,after})}
 else if(PHASE==='airport'){await nav('speak');log('MISSION',await openAirport());log('HIT_HOME',await hit('[data-nav="home"]:visible'));await back();await nav('home')}
 else if(PHASE==='tenx'){await nav('speak');const start=await page.evaluate(()=>window.__P.uniqueAdds);for(let i=1;i<=10;i++){log('CYCLE_START',i);await openAirport();await back();log('CYCLE_DONE',i)}const end=await page.evaluate(()=>window.__P.uniqueAdds);ok(end-start===10,`10x unique mount delta ${end-start}`)}
 else if(PHASE==='rapid'){await nav('speak');const start=await page.evaluate(()=>window.__P.uniqueAdds);const dispatched=await page.evaluate(()=>{const b=document.querySelector('[data-canonical-scenario="airport"]');if(!b)throw new Error('airport button missing');return[b.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true})),b.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true}))]});log('SYNC_DOUBLE_DISPATCH',dispatched);await page.waitForTimeout(160);const s=await snap(),delta=s.uniqueAdds-start;log('RAPID_STATE',{delta,...s});ok(s.mission===1,'rapid final mission one');ok(delta===1,`rapid unique mount delta ${delta}`);await alive('rapid')}
 else if(PHASE==='access'){await nav('speak');await page.evaluate(()=>{const sb=window.llSupabase,orig=sb.rpc.bind(sb);sb.rpc=async(n,a)=>n==='my_membership'?{data:null,error:new Error('SIMULATED_ACCESS_FAILURE')}:orig(n,a)});await page.locator('[data-canonical-scenario="transport"]:visible').first().click();await page.waitForTimeout(80);let s=await snap();ok(await page.locator('.speakError:visible').count()===1,'access error scoped');ok(s.mission===0&&s.inert.length===0,'access error no mission/inert');await alive('access-error');await page.locator('[data-speak-retry]:visible').first().click();await page.waitForTimeout(50);s=await snap();ok(s.active[0]==='view-speak'&&s.mission===0,'access retry interactive');await page.locator('[data-canonical-scenario="transport"]:visible').first().click();await page.waitForTimeout(60);await page.locator('[data-speak-back]:visible').first().click();await page.waitForTimeout(50);s=await snap();ok(s.hash==='#speak'&&s.mission===0,'access back interactive')}
 else if(PHASE==='mobile'){await nav('speak');await openAirport();await back();await nav('home');await nav('profile');const s=await snap();ok(s.inert.length===0&&s.bodyPE!=='none','mobile no input residue')}
 else fail(`unknown phase ${PHASE}`);
 log('DONE',await snap());
}catch(e){log('FATAL',e.stack||e.message);process.exitCode=1}finally{await browser.close().catch(()=>{})}
